"use client";

import "./avatar.css";

import {
  createContext,
  useContext,
  useState,
  type ComponentProps,
} from "react";
import { cx } from "./cx";

type AvatarContextValue = {
  loaded: boolean;
  setLoaded: (loaded: boolean) => void;
};

const AvatarContext = createContext<AvatarContextValue>({
  loaded: false,
  setLoaded: () => {},
});

export type AvatarProps = ComponentProps<"span"> & {
  size?: "sm" | "md" | undefined;
};

export type AvatarImageProps = ComponentProps<"img">;

export type AvatarFallbackProps = ComponentProps<"span">;

export function Avatar({ size = "md", className, ...rest }: AvatarProps) {
  const [loaded, setLoaded] = useState(false);

  return (
    <AvatarContext.Provider value={{ loaded, setLoaded }}>
      <span
        className={cx("ns-avatar", className)}
        data-size={size === "md" ? undefined : size}
        {...rest}
      />
    </AvatarContext.Provider>
  );
}

export function AvatarImage({
  className,
  alt = "",
  onError,
  onLoad,
  ...rest
}: AvatarImageProps) {
  const { setLoaded } = useContext(AvatarContext);
  const [failed, setFailed] = useState(false);
  if (failed) return null;
  return (
    <img
      className={cx("ns-avatar__image", className)}
      alt={alt}
      onLoad={(event) => {
        setLoaded(true);
        onLoad?.(event);
      }}
      onError={(event) => {
        setFailed(true);
        setLoaded(false);
        onError?.(event);
      }}
      {...rest}
    />
  );
}

export function AvatarFallback({ className, ...rest }: AvatarFallbackProps) {
  const { loaded } = useContext(AvatarContext);
  if (loaded) return null;
  return <span className={cx("ns-avatar__fallback", className)} {...rest} />;
}

@layer components {
  .ns-avatar {
    position: relative;
    display: inline-grid;
    place-items: center;
    overflow: hidden;
    width: 2rem;
    height: 2rem;
    border: 1px solid var(--face-line, #626262);
    border-radius: 999px;
    background: var(--face);
    background-clip: padding-box;
    box-shadow: var(--float, 0 8px 20px rgb(0 0 0 / 12%));
    color: var(--on-key, #111);
    font-size: var(--type-sm, 0.8rem);
    font-weight: var(--weight-medium, 500);
    line-height: 1;
    vertical-align: middle;
  }

  .ns-avatar[data-size="sm"] {
    width: 1.5rem;
    height: 1.5rem;
    font-size: var(--type-xs, 0.64rem);
  }

  .ns-avatar__image {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  .ns-avatar__fallback {
    display: grid;
    place-items: center;
  }
}
